// The matchup's Deep dive tab: all the sim evidence behind a guide in one place (data: the guide's `deep`, generated by
// docs/research/strategy/sim/scripts/deep-5v3.mjs). Every six tested, ranked, each with its leads, notes and paste (copy or
// import as a team); the calcs for your six; his modelled sixes with pastes; how the numbers were made. Only for your own
// side, like the guide (prep-guide.js guideOf).
import * as C from './prep-copy.js';
import { esc, btn, h2 } from './prep-ui.js';
import { guideOf } from './prep-guide.js';
import { importTeamText } from './prep-teams.js';

const D = C.DEEP;
/** The Deep dive of matchup m (validated guide.deep), or null. */
export function deepOf(P, m) {
  const g = m ? guideOf(P, m.pov.name, m.opp.name)?.guide : null;
  return g?.deep?.sixes.length ? { g, d: g.deep } : null;
}
export const has = (P, m) => !!deepOf(P, m);

const pctTxt = (x) => (x == null ? '—' : `${Number(x).toFixed(1)}%`);
const sub = (x) => (x ? `${pctTxt(x.pct)}` : '—');
// a paired difference: signed points ± 95%; a tie (interval crosses 0) is muted
const delta = (x) => {
  if (!x) return '<span class="muted">—</span>';
  const tie = Math.abs(x.d) <= x.ci;
  return `<span class="dd-d ${tie ? 'tie' : x.d > 0 ? 'up' : 'down'}" title="${esc(D.deltaTip(x.n))}">${x.d > 0 ? '+' : ''}${x.d.toFixed(1)} ±${x.ci.toFixed(1)}</span>`;
};
const names = (P, ids) => ids.map((id) => esc(P.spName(id))).join(' + ');
const anchor = (s) => `dd-${s.id}`;
const running = (r) => r && r.n < 900;

function ranking(P, d) {
  const rows = d.sixes.filter((s) => s.results).sort((a, b) => b.results.zhuzi - a.results.zhuzi);
  return `<div class="dd-scroll"><table class="dd-table"><thead><tr><th>${esc(D.six)}</th><th>${esc(D.colZhuzi)}</th><th>${esc(D.colAnti)}</th><th>${esc(D.colRock)}</th><th>${esc(D.colVs)}</th></tr></thead><tbody>
    ${rows.map((s) => `<tr${s.tag === 'yours' ? ' class="dd-yours"' : ''}><th scope="row">${btn(s.name, 'dd-jump', { six: s.id }, { cls: 'linkish' })}${running(s.results) ? ` <span class="small muted">${esc(D.partial(s.results.n))}</span>` : ''}</th>
      <td><b>${pctTxt(s.results.zhuzi)}</b></td><td>${sub(s.results.anti)}</td><td>${sub(s.results.rock)}</td><td>${s.tag === 'yours' ? `<span class="muted">${esc(D.base)}</span>` : delta(s.results.vsYours)}</td></tr>`).join('')}
  </tbody></table></div><p class="small muted">${esc(D.rankHelp)}</p>`;
}

function engine(P, d) {
  const rows = d.sixes.filter((s) => s.engine);
  if (!rows.length) return `<p class="small muted">${esc(D.enginePending)}</p>`;
  return `<div class="dd-scroll"><table class="dd-table"><thead><tr><th>${esc(D.six)}</th><th>${esc(D.colZhuzi)}</th><th>${esc(D.colAnti)}</th><th>${esc(D.colVs)}</th></tr></thead><tbody>
    ${rows.sort((a, b) => b.engine.zhuzi - a.engine.zhuzi).map((s) => `<tr${s.tag === 'yours' ? ' class="dd-yours"' : ''}><th scope="row">${esc(s.name)}${running(s.engine) && s.engine.n < 230 ? ` <span class="small muted">${esc(D.partial(s.engine.n))}</span>` : ''}</th><td><b>${pctTxt(s.engine.zhuzi)}</b></td><td>${sub(s.engine.anti)}</td><td>${s.tag === 'yours' ? `<span class="muted">${esc(D.base)}</span>` : delta(s.engine.vsYours)}</td></tr>`).join('')}
  </tbody></table></div><p class="small muted">${esc(D.engineHelp)}</p>`;
}

function sixCard(P, s, open) {
  const r = s.results;
  const leads = s.leads.length ? `<div class="dd-scroll"><table class="dd-table dd-leads"><thead><tr><th>${esc(D.ifHe)}</th><th>${esc(D.lead)}</th><th>${esc(D.back)}</th></tr></thead><tbody>
    ${s.leads.map((l) => `<tr><td>${esc(l.if.replace(/^their 6 includes\s+/i, ''))}</td><td><b>${names(P, l.lead)}</b></td><td>${names(P, l.bring4.filter((id) => !l.lead.includes(id)))}</td></tr>`).join('')}
  </tbody></table></div>${s.leads.some((l) => l.fit) ? `<p class="small muted">${esc(D.leadsHelp)}</p>` : ''}` : `<p class="small muted">${esc(D.noLeads)}</p>`;
  return `<details class="card dd-six${s.tag === 'yours' ? ' dd-yours' : ''}" id="${anchor(s)}"${open ? ' open' : ''}><summary><b>${esc(s.name)}</b>${s.tag === 'yours' ? ` <span class="gpill">${esc(D.yoursPill)}</span>` : s.tag === 'guide' ? ` <span class="gpill">${esc(D.guidePill)}</span>` : ''}
      ${r ? `<span class="small dd-sum">${esc(D.colZhuzi)} <b>${pctTxt(r.zhuzi)}</b> · ${esc(D.colAnti)} ${sub(r.anti)}${s.tag === 'yours' ? '' : ` · ${D.colVs} ${delta(r.vsYours)}`}</span>` : ''}</summary>
    <p>${esc(s.change)}</p>
    ${r && r.vsYoursAnti ? `<p class="small">${esc(D.vsAnti)} ${delta(r.vsYoursAnti)}${r.rock ? ` · ${esc(D.colRock)} ${sub(r.rock)}` : ''}</p>` : r?.rock ? `<p class="small">${esc(D.colRock)} ${sub(r.rock)}</p>` : ''}
    ${s.notes.length ? `<ul class="gd-list">${s.notes.map((n) => `<li>${esc(n)}</li>`).join('')}</ul>` : ''}
    <h4>${esc(D.leadsHead)}</h4>${leads}
    <h4>${esc(D.paste)}</h4><pre class="dd-paste" tabindex="0">${esc(s.paste)}</pre>
    <p>${btn(D.copy, 'dd-copy', { kind: 'six', six: s.id })} ${btn(D.importTeam, 'dd-import', { six: s.id })}</p></details>`;
}

function calcs(P, d) {
  if (!d.calcs.length) return '';
  const line = (c) => `<li>${esc(P.spName(c.attacker.id))} ${esc(P.name('moves', c.move))}${c.field?.weather ? ` <span class="small muted">(${esc(c.field.weather)})</span>` : ''} → ${esc(P.spName(c.defender.id))}: <b>${esc(c.range)}</b>${c.verdict ? ` · ${esc(c.verdict)}` : ''}${c.why ? `<br><span class="small muted">${esc(c.why)}</span>` : ''}</li>`;
  const ours = d.calcs.filter((c) => c.attacker.set === 'ours'), theirs = d.calcs.filter((c) => c.attacker.set !== 'ours');
  return `<h3>${esc(D.calcsHead)}</h3><p class="small muted">${esc(D.calcsHelp)}</p>
    <h4>${esc(D.yourHits)}</h4><ul class="gd-list dd-calcs">${ours.map(line).join('')}</ul>
    ${theirs.length ? `<h4>${esc(D.hisHits)}</h4><ul class="gd-list dd-calcs">${theirs.map(line).join('')}</ul>` : ''}`;
}

function opponents(P, d, coach) {
  if (!d.opponents.length) return '';
  const rows = [...d.opponents].sort((a, b) => (b.weight ?? -1) - (a.weight ?? -1));
  return `<h3>${esc(D.hisHead(coach))}</h3><p class="small muted">${esc(D.hisHelp)}</p>
    ${rows.map((o) => `<details class="card dd-opp"><summary><b>${esc(o.label)}</b> <span class="small muted">${o.weight == null ? esc(D.extra) : esc(D.weight(Math.round(1000 * o.weight) / 10))}${o.anti ? ` · ${esc(D.antiTag)}` : ''}</span></summary>
      ${o.why ? `<p class="small">${esc(o.why)}</p>` : ''}<pre class="dd-paste" tabindex="0">${esc(o.paste)}</pre><p>${btn(D.copy, 'dd-copy', { kind: 'opp', six: o.id })}</p></details>`).join('')}`;
}

/** The tab body. */
export function tab(P, m) {
  const x = deepOf(P, m);
  if (!x) return `${h2(D.head(m.opp.name))}<p>${esc(D.none)}</p>`;
  const { g, d } = x;
  const yours = d.sixes.find((s) => s.tag === 'yours');
  const ranked = d.sixes.filter((s) => s.results);
  const top = [...ranked].sort((a, b) => b.results.zhuzi - a.results.zhuzi)[0];
  const topAnti = [...ranked].filter((s) => s.results.anti).sort((a, b) => b.results.anti.pct - a.results.anti.pct)[0];
  const short = [
    yours?.results ? D.yourLine(yours.name, pctTxt(yours.results.zhuzi), sub(yours.results.anti)) : '',
    top ? D.topLine(top.name, pctTxt(top.results.zhuzi)) : '',
    topAnti ? D.topAntiLine(topAnti.name, sub(topAnti.results.anti)) : '',
    d.rockSlide?.all ? D.rsLine(d.rockSlide.all, d.rockSlide.inf) : '',
  ].filter(Boolean);
  const order = [...d.sixes].sort((a, b) => (a.tag === 'yours' ? -1 : b.tag === 'yours' ? 1 : (b.results?.zhuzi ?? 0) - (a.results?.zhuzi ?? 0)));
  return `${h2(D.head(g.coach))}<p class="small muted">${esc(D.sub(d.written, d.sixes.length))}</p>
    <div class="card"><b>${esc(D.short)}</b><ul class="gd-list">${short.map((s) => `<li>${esc(s)}</li>`).join('')}</ul></div>
    <h3>${esc(D.rankHead)}</h3>${ranking(P, d)}
    <h3>${esc(D.engineHead)}</h3>${engine(P, d)}
    <h3>${esc(D.sixesHead)}</h3>${order.map((s, i) => sixCard(P, s, i === 0)).join('')}
    ${calcs(P, d)}
    ${opponents(P, d, g.coach)}
    <details class="card"><summary><b>${esc(D.methodHead)}</b></summary><ul class="gd-list">${d.method.map((s) => `<li>${esc(s)}</li>`).join('')}</ul>
      ${d.caveats.length ? `<p><b>${esc(D.caveatsHead)}</b></p><ul class="gd-list">${d.caveats.map((s) => `<li>${esc(s)}</li>`).join('')}</ul>` : ''}</details>`;
}

const found = (P) => deepOf(P, P.match?.());
export const actions = {
  'dd-copy': async (t, P) => {
    const x = found(P);
    const item = x && (t.dataset.kind === 'opp' ? x.d.opponents : x.d.sixes).find((s) => s.id === t.dataset.six);
    if (!item) return;
    try { await P.app.copyText(item.paste); P.toast(D.copied(item.name ?? item.label)); } catch { P.toast(D.copyFailed); }
  },
  'dd-import': (t, P) => {
    const x = found(P);
    const s = x?.d.sixes.find((v) => v.id === t.dataset.six);
    if (!s) return;
    importTeamText(P, `=== [gen9championsvgc2026regmc] ${D.teamName(x.g.coach, s.name)} ===\n\n${s.paste}`, null, { reason: D.reason(x.g.coach), bringFor: x.g.coach });
  },
  'dd-jump': (t) => {
    const el = t.ownerDocument?.getElementById(`dd-${t.dataset.six}`);
    if (el) { el.open = true; el.scrollIntoView({ block: 'start' }); }
  },
};
